(function(root){
  const X=root.WorkLife;
  function render({app,p,W,R,esc,persist,finish,back}){
    p.extraAnswers=p.extraAnswers||{};
    p.funAnswers=Array.isArray(p.funAnswers)?p.funAnswers:Array(4).fill(null);
    const items=itemsFor(W,X);
    const page=Math.min(Math.ceil(items.length/8)-1,Math.max(0,p.page||0)),start=page*8,current=items.slice(start,start+8),last=start+8>=items.length;
    p.page=page;
    const answered=x=>x.kind==='mate'?!!p.answers[x.q.id]:x.kind==='fun'?(p.funAnswers[x.q.id]===0||p.funAnswers[x.q.id]===1):X.validAnswer(x.q,p.extraAnswers[x.q.id]);
    const required=items.filter(x=>!x.q.optional),count=required.filter(answered).length;
    function extra(q){
      const v=p.extraAnswers[q.id],field=`extra-${q.id}`;
      if(q.type==='text')return `<textarea class="input" id="${field}" data-text="${q.id}" maxlength="2000" aria-label="${esc(q.text)}" placeholder="의견을 자유롭게 적어주세요 (선택, 2,000자 이내)">${esc(v||'')}</textarea>`;
      if(q.type==='grid')return q.rows.map((name,i)=>`<div class="survey-grid-row"><label class="field-label" for="${field}-${i}">${esc(name)}</label><p class="micro">${esc(q.descriptions[i])}</p><select class="input select" id="${field}-${i}" data-grid="${q.id}" data-row="${i}"><option value="">선택해주세요</option>${q.options.map((s,j)=>`<option value="${j}" ${v?.[i]===j?'selected':''}>${esc(s)}</option>`).join('')}</select></div>`).join('');
      return `<p class="micro">${q.type==='multi'?`복수 선택${q.max?' · 최대 '+q.max+'개':''}`:'하나 선택'}</p><div class="extra-choices">${q.options.map((s,i)=>`<label class="extra-choice"><input type="${q.type==='multi'?'checkbox':'radio'}" name="${field}" data-extra="${q.id}" value="${i}" ${(q.type==='multi'?v?.includes(i):v===i)?'checked':''}><span>${esc(s)}</span></label>`).join('')}</div>${q.options.includes('기타')?`<label class="field-label" for="other-${q.id}">기타 의견 (선택)</label><textarea class="input" id="other-${q.id}" data-other="${q.id}" maxlength="500">${esc(p.extraAnswers[q.id+'Other']||'')}</textarea>`:''}`;
    }
    app.innerHTML=`<section class="page"><div class="survey-heading"><div class="flex spread"><span class="eyebrow">OUR WORKSHOP</span><span class="pill">${esc(p.name)}</span></div><h1>함께 일했던 순간을 돌아봐요</h1><div class="progress" role="progressbar" aria-label="설문 진행" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="${required.length}"><span style="width:${count/required.length*100}%"></span></div><p class="micro">${page+1} / ${Math.ceil(items.length/8)} 페이지 · 총 ${items.length}문항 · 필수 응답 <span id="mixed-count">${count} / ${required.length}</span> · 선택 의견은 비워도 돼요</p></div>${current.map((x,i)=>{const q=x.q;return `<section class="question" id="mixed-${i}"><h2><small>${start+i+1}</small>${esc(q.text)}${q.optional?' <span class="micro">(선택)</span>':''}</h2>${x.kind==='extra'?extra(q):x.kind==='fun'?`<div class="balance-game-options">${q.options.map((text,index)=>`<button class="btn ${p.funAnswers[q.id]===index?'primary':'ghost'}" data-fun="${q.id}" data-value="${index}" aria-pressed="${p.funAnswers[q.id]===index}">${esc(text)}</button>`).join('<span class="game-vs" aria-hidden="true">VS</span>')}</div>`:(()=>{const a=R.questionFor(q,p.role,p.orderSeed);return `<p class="job-example">${esc(a.context)}</p><div class="scale" role="group" aria-label="${esc(q.text)}">${a.options.map(o=>`<button data-mate="${q.id}" data-value="${o.id}" class="${p.answers[q.id]===o.id?'selected':''}" aria-pressed="${p.answers[q.id]===o.id}"><span class="option-check" aria-hidden="true">${p.answers[q.id]===o.id?'✓':''}</span><span>${esc(o.text)}</span></button>`).join('')}</div>`;})()}</section>`;}).join('')}<p class="error" id="mixed-error" role="alert"></p><div class="survey-nav"><button class="btn ghost" id="mixed-prev">${page?'이전 페이지':'이름·직군 수정'}</button><span class="micro">자동 저장</span><button class="btn primary" id="mixed-next">${last?'설문 완료하기':'다음 페이지'}</button></div></section>`;
    const error=msg=>app.querySelector('#mixed-error').textContent=msg;
    const updateProgress=()=>{const n=required.filter(answered).length;app.querySelector('.progress').setAttribute('aria-valuenow',n);app.querySelector('.progress span').style.width=n/required.length*100+'%';app.querySelector('#mixed-count').textContent=`${n} / ${required.length}`;};
    app.querySelectorAll('[data-fun]').forEach(button=>button.onclick=()=>{p.funAnswers[+button.dataset.fun]=+button.dataset.value;persist();app.querySelectorAll(`[data-fun="${button.dataset.fun}"]`).forEach(b=>{const yes=+b.dataset.value===+button.dataset.value;b.classList.toggle('primary',yes);b.classList.toggle('ghost',!yes);b.setAttribute('aria-pressed',yes);});error('');updateProgress();});

    app.querySelectorAll('[data-mate]').forEach(b=>b.onclick=()=>{p.answers[+b.dataset.mate]=+b.dataset.value;persist();app.querySelectorAll(`[data-mate="${b.dataset.mate}"]`).forEach(t=>{const yes=+t.dataset.value===+b.dataset.value;t.classList.toggle('selected',yes);t.setAttribute('aria-pressed',yes);t.querySelector('.option-check').textContent=yes?'✓':'';});error('');updateProgress();});
    app.querySelectorAll('[data-extra]').forEach(input=>input.onchange=()=>{const q=X.questions.find(q=>q.id===input.dataset.extra),v=+input.value;if(q.type==='single')p.extraAnswers[q.id]=v;else{let selected=p.extraAnswers[q.id]||[];selected=input.checked?[...selected.filter(x=>!q.exclusive?.includes(x)),v]:selected.filter(x=>x!==v);if(input.checked&&q.exclusive?.includes(v))selected=[v];if(selected.length>(q.max||q.options.length)){input.checked=false;error(`선택은 최대 ${q.max}개까지 가능해요.`);return;}p.extraAnswers[q.id]=selected;app.querySelectorAll(`[data-extra="${q.id}"]`).forEach(t=>t.checked=selected.includes(+t.value));}persist();error('');updateProgress();});
    app.querySelectorAll('[data-grid]').forEach(input=>input.onchange=()=>{const id=input.dataset.grid;p.extraAnswers[id]=p.extraAnswers[id]||Array(7).fill(null);p.extraAnswers[id][+input.dataset.row]=input.value===''?null:+input.value;persist();error('');updateProgress();});
    app.querySelectorAll('[data-text],[data-other]').forEach(input=>input.oninput=()=>{const id=input.dataset.text||input.dataset.other+'Other';p.extraAnswers[id]=input.value;persist();});
    app.querySelector('#mixed-prev').onclick=()=>{if(!page){back();return;}p.page=page-1;persist();render({app,p,W,R,esc,persist,finish,back});window.scrollTo(0,0);};
    app.querySelector('#mixed-next').onclick=()=>{const missing=current.findIndex(x=>!answered(x));if(missing>=0){error('아직 답하지 않은 문항을 확인해주세요.');const el=app.querySelector('#mixed-'+missing);el.scrollIntoView({behavior:'smooth',block:'center'});el.querySelector('input,select,button,textarea')?.focus({preventScroll:true});return;}if(last){if(!W.validProfile(p)||!X.complete(p.extraAnswers)){error('앞 페이지에 답하지 않은 문항이 있어요.');p.page=0;persist();render({app,p,W,R,esc,persist,finish,back});return;}finish();}else{p.page=page+1;persist();render({app,p,W,R,esc,persist,finish,back});window.scrollTo(0,0);}};
  }
  function itemsFor(W,X){const items=[];for(let i=0;i<12;i++){items.push(...W.questions.slice(i*2,i*2+2).map(q=>({kind:'mate',q})),{kind:'extra',q:X.questions[i]});if(i%3===2)items.push({kind:'fun',q:W.funQuestions[Math.floor(i/3)]});}return items;}
  root.MixedSurvey={render,itemsFor};if(typeof module!=='undefined')module.exports=root.MixedSurvey;
})(typeof window==='undefined'?globalThis:window);
